  1630          FLAC__ASSERT(used_bits % 8 == 0);
  1631          length -= (used_bits / 8);
  1632          if(!FLAC__bitreader_skip_byte_block_aligned_no_crc(decoder->private_->input, length))
  1633                  return false; /* read_callback_ sets the state for us */
